/* Màn chọn phương tiện: lớp phủ chặn chuột vào canvas, phủ cả các bảng; có ô chọn ngôn ngữ riêng (#exLang) */
.ex-chooser{position:fixed;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;background:rgba(6,10,13,.72);}
.ex-lang{display:block;margin:0 0 12px;width:max-content;}
.ex-box{position:static;max-width:min(720px,100%);max-height:100%;overflow-y:auto;padding:22px 24px;box-sizing:border-box;}
.ex-box h2{margin:0 0 16px;font-family:var(--font-display);font-weight:600;font-size:26px;line-height:1.15;color:var(--gold);text-wrap:balance;}
.ex-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;}
.ex-card{display:flex;flex-direction:column;align-items:flex-start;gap:4px;min-height:84px;padding:12px 14px;text-align:start;}
.ex-card b{font-weight:600;font-size:14px;color:var(--text);}
.ex-card span,.ex-card i{font-style:normal;font-size:11.5px;line-height:1.4;color:var(--muted);}
.ex-card:disabled{opacity:.55;cursor:not-allowed;}
.ex-card:disabled .ex-note{color:var(--gold);}
.ex-card:focus-visible{outline:2px solid var(--gold);outline-offset:2px;}
