    // Chuỗi tổng: nén nhẹ → loa
    A.master = ctx.createGain(); A.master.gain.value = 0;
    const comp = ctx.createDynamicsCompressor(); comp.threshold.value = -18; comp.ratio.value = 3;
    A.master.connect(comp).connect(ctx.destination);
