    const nl = ctx.sampleRate * 4, nb = ctx.createBuffer(1, nl, ctx.sampleRate), nd = nb.getChannelData(0);
    let last = 0; for (let i = 0; i < nl; i++) { last = (last + 0.02 * (R() * 2 - 1)) / 1.02; nd[i] = last * 3.5; }
