import { readFileSync, writeFileSync } from 'node:fs';
const edit = (f, fn) => { let s = readFileSync(f, 'utf8'); const cr = s.includes('\r\n'); if (cr) s = s.replace(/\r\n/g, '\n'); s = fn(s); if (cr) s = s.replace(/\n/g, '\r\n'); writeFileSync(f, s); };
const rep = (s, a, b) => { if (!s.includes(a)) throw new Error('không thấy: ' + a); return s.replace(a, b); };
edit('scripts/add-drive-locales.mjs', (s) => {
  s = rep(s, ` drRoster (tên chế độ trong danh sách người chơi),`, ``);
  s = rep(s, `'drBrake', 'drRoster', `, `'drBrake', `);
  for (const [a, b] of [[`'PHANH', 'Lái xe', `, `'PHANH', `], [`'BRAKE', 'Driving', `, `'BRAKE', `], [`'브레이크', '운전', `, `'브레이크', `], [`'ブレーキ', '運転', `, `'ブレーキ', `],
    [`'刹车', '驾驶', `, `'刹车', `], [`'เบรก', 'ขับรถ', `, `'เบรก', `], [`'بنزين', 'فرامل', 'يقودون', `, `'تسارع', 'فرامل', `], [`'ब्रेक', 'ड्राइविंग', `, `'ब्रेक', `], [`'ТОРМОЗ', 'За рулём', `, `'ТОРМОЗ', `]]) s = rep(s, a, b);
  s = rep(s, `   Bản dịch 8 ngôn ngữ`, `   Sửa cuối D-034: bỏ khóa drRoster (không còn chỗ dùng; danh sách người chơi dùng drRosterAll); ar drGas "بنزين" (xăng) → "تسارع" (tăng tốc), cần người bản ngữ duyệt.
   Bản dịch 8 ngôn ngữ`);
  return s;
});
for (const code of ['vi', 'en', 'ko', 'ja', 'zh', 'th', 'ar', 'hi', 'ru']) edit(`src/i18n/locales/${code}.json`, (s) => {
  const j = JSON.parse(s);
  if (!('drRoster' in j)) throw new Error(code + ' không có drRoster');
  delete j.drRoster;
  if (code === 'ar') { if (j.drGas !== 'بنزين') throw new Error('ar drGas khác'); j.drGas = 'تسارع'; }
  const out = JSON.stringify(j, null, 2) + '\n';
  return out;
});
EOF
node "$TEMP/ed7.mjs" && node --check scripts/add-drive-locales.mjs && git diff --stat && git diff src/i18n/locales/ar.json src/i18n/locales/vi.json

